const uid = () => `${Date.now().toString(36)}-${Math.random().toString(36).slice(2,8)}`;
function ensureIds(){let changed=false;Object.entries(configs).forEach(([,cfg])=>collectionMap[cfg.key].forEach(row=>{if(!row[cfg.id]){row[cfg.id]=uid();changed=true}}));return changed}
function state(){return {...Object.fromEntries(Object.entries(collectionMap).map(([key,rows])=>[key,rows])),shows:[]}}
const recordChange=(collection,record)=>({collection,id:record[Object.values(configs).find(config=>config.key===collection).id],record});
async function saveState(){const response=await fetch("/api/state",{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(state())});if(response.status===401){currentUser=null;authScreen(true,"Sua sessão expirou. Entre novamente.");throw new Error("Sessão expirada")}if(!response.ok)throw new Error((await response.json()).error||"Não foi possível salvar");drawNotifications()}
async function saveChanges(changes){const response=await fetch("/api/state/changes",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({changes})});if(response.status===401){currentUser=null;authScreen(true,"Sua sessão expirou. Entre novamente.");throw new Error("Sessão expirada")}if(!response.ok)throw new Error((await response.json()).error||"Não foi possível salvar");drawNotifications()}
async function loadState(){const response=await fetch("/api/state");if(!response.ok)throw new Error((await response.json()).error||"Não foi possível carregar");const saved=await response.json();Object.entries(collectionMap).forEach(([key,rows])=>{if(Array.isArray(saved[key]))rows.splice(0,rows.length,...saved[key])});const changed=migrateLegacyShows(Array.isArray(saved.shows)?saved.shows:Object.keys(saved).length?[]:shows)|ensureIds();if(changed)await saveState()}
const classToken = value => String(value??"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9-]+/g,"-").replace(/^-|-$/g,"")||"default";
const status = value => `status status-${classToken(value)}`;
const avatar = (text,tone="blue") => `<span class="avatar avatar-${classToken(tone)}">${escapeHtml(text)}</span>`;
const header = (eyebrow,title,description,action="Adicionar novo",secondary="") => `<div class="page-header"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="page-description">${description}</p></div>${action||secondary?`<div class="page-actions">${secondary?`<button class="secondary-button" data-secondary-action><span>▦</span>${secondary}</button>`:""}${action?`<button class="primary-button" data-primary-action><span>＋</span>${action}</button>`:""}</div>`:""}</div>`;
const kpis = rows => `<div class="kpi-grid">${rows.map(([a,b,c="+12,4%"])=>`<div class="kpi"><span class="kpi-icon">↗</span><p>${a}</p><strong>${b}</strong><small>${c}${String(c).startsWith("+")?" <em>vs. mês anterior</em>":""}</small></div>`).join("")}</div>`;

