function emptyState(message){return `<div class="empty-state"><strong>${message}</strong><p>Use o botão superior para criar o primeiro registro.</p></div>`}
function escapeHtml(value){return String(value??"").replace(/[&<>"']/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[char]))}
function fieldOptions(options,value){let choices=typeof options==="function"?options():options;if(value&&!choices.some(option=>String(Array.isArray(option)?option[0]:option)===String(value)))choices=[value,...choices];return choices.map(option=>{const pair=Array.isArray(option)?option:[option,option];return `<option value="${escapeHtml(pair[0])}" ${String(pair[0])===String(value)?"selected":""}>${escapeHtml(pair[1])}</option>`}).join("")}
function socialIcon(key,size="medium"){const px=size==="small"?14:size==="large"?20:16,stroke=size==="small"?1.8:2;const icons={youtube:`<svg viewBox="0 0 24 24" width="${px}" height="${px}" aria-hidden="true"><rect x="3.2" y="6" width="17.6" height="12" rx="4.2" fill="currentColor" opacity=".12"></rect><path d="M10 9l5 3-5 3z" fill="currentColor"></path><rect x="3.8" y="6.6" width="16.4" height="10.8" rx="3.6" fill="none" stroke="currentColor" stroke-width="${stroke}"></rect></svg>`,instagram:`<svg viewBox="0 0 24 24" width="${px}" height="${px}" aria-hidden="true"><rect x="4.3" y="4.3" width="15.4" height="15.4" rx="4.5" fill="none" stroke="currentColor" stroke-width="${stroke}"></rect><circle cx="12" cy="12" r="3.6" fill="none" stroke="currentColor" stroke-width="${stroke}"></circle><circle cx="17.2" cy="6.8" r="1.1" fill="currentColor"></circle></svg>`,tiktok:`<svg viewBox="0 0 24 24" width="${px}" height="${px}" aria-hidden="true"><path d="M13 5v8.2a3.6 3.6 0 1 1-2.7-3.5" fill="none" stroke="currentColor" stroke-width="${stroke}" stroke-linecap="round" stroke-linejoin="round"></path><path d="M13 5c1.1 2 2.5 3.2 5 3.5" fill="none" stroke="currentColor" stroke-width="${stroke}" stroke-linecap="round"></path></svg>`,spotify:`<svg viewBox="0 0 24 24" width="${px}" height="${px}" aria-hidden="true"><circle cx="12" cy="12" r="8.3" fill="none" stroke="currentColor" stroke-width="${stroke}"></circle><path d="M8 10.2c3-1 5.8-.8 8.1.5M8.7 13c2.4-.7 4.6-.6 6.5.3M9.5 15.5c1.8-.4 3.5-.3 5 .2" fill="none" stroke="currentColor" stroke-width="${stroke}" stroke-linecap="round"></path></svg>`};return icons[key]||""}
