function openModal(content,size="normal"){
  document.querySelector(".modal-overlay")?.remove();
  document.body.insertAdjacentHTML("beforeend",`<div class="modal-overlay"><section class="app-modal modal-${size}" role="dialog" aria-modal="true">${content}</section></div>`);
  const overlay=document.querySelector(".modal-overlay");
  overlay.addEventListener("click",event=>{if(event.target===overlay||event.target.closest("[data-close-modal]"))overlay.remove()});
  document.addEventListener("keydown",function close(event){if(event.key==="Escape"&&!document.querySelector(".crop-overlay")){overlay.remove();document.removeEventListener("keydown",close)}});
  return overlay;
}
const calendarMonths=["Janeiro","Fevereiro","Março","Abril","Maio","Junho","Julho","Agosto","Setembro","Outubro","Novembro","Dezembro"];
function todayInSaoPaulo(){const parts=Object.fromEntries(new Intl.DateTimeFormat("en",{timeZone:"America/Sao_Paulo",year:"numeric",month:"numeric",day:"numeric"}).formatToParts(new Date()).filter(part=>part.type!=="literal").map(part=>[part.type,Number(part.value)]));return new Date(parts.year,parts.month-1,parts.day)}
function agendaDate(value){
  const clean=String(value||"").trim().normalize("NFD").replace(/[\u0300-\u036f]/g,"").toUpperCase();
  if(clean==="HOJE")return todayInSaoPaulo();
  if(clean==="AMANHA"){const tomorrow=todayInSaoPaulo();tomorrow.setDate(tomorrow.getDate()+1);return tomorrow}
  let match=clean.match(/^(\d{4})-(\d{2})-(\d{2})$/);if(match)return new Date(Number(match[1]),Number(match[2])-1,Number(match[3]));
  match=clean.match(/^(\d{1,2})\/(\d{1,2})(?:\/(\d{4}))?$/);if(match)return new Date(Number(match[3]||2026),Number(match[2])-1,Number(match[1]));
  match=clean.match(/^(\d{1,2})\s+([A-Z]{3,9})(?:\s+(\d{4}))?$/);if(match){const names=["JAN","FEV","MAR","ABR","MAI","JUN","JUL","AGO","SET","OUT","NOV","DEZ"],month=names.indexOf(match[2].slice(0,3));if(month>=0)return new Date(Number(match[3]||2026),month,Number(match[1]))}
  return null;
}
const dateKey=date=>date?`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,"0")}-${String(date.getDate()).padStart(2,"0")}`:"";
function agendaWeek(){const today=todayInSaoPaulo(),monday=new Date(today),offset=(today.getDay()+6)%7;monday.setDate(today.getDate()-offset);return Array.from({length:7},(_,index)=>{const date=new Date(monday);date.setDate(monday.getDate()+index);return date})}
function agendaPage(){const week=agendaWeek(),selected=dateKey(todayInSaoPaulo()),todayRows=agenda.filter(row=>dateKey(agendaDate(row[1]))===selected);return `${header("PRODUÇÃO","Agenda editorial","Convites, confirmações e logística de estúdio sem ruído.","Novo compromisso","Agenda completa")}<div class="calendar-strip">${week.map(date=>`<button class="${dateKey(date)===selected?"today":""}" data-agenda-date="${dateKey(date)}"><small>${date.toLocaleDateString("pt-BR",{weekday:"short"}).replace(".","").toUpperCase()}</small><strong>${date.getDate()}</strong>${agenda.some(row=>dateKey(agendaDate(row[1]))===dateKey(date))?"<i></i>":""}</button>`).join("")}</div><div class="table-toolbar"><div class="filter-pills" data-agenda>${["Todos","Confirmado","Pendente","Cancelado"].map((value,index)=>`<button class="${index===0?"active":""}" data-value="${value}">${value}</button>`).join("")}</div><button class="select-button" data-agenda-week>Esta semana</button></div><div class="data-table"><div class="table-head"><span>HORÁRIO</span><span>CONVIDADO / PROGRAMA</span><span>CHEGADA</span><span>STATUS</span><span>OBSERVAÇÕES</span><span></span></div><div id="agenda-list">${agendaRows(todayRows)}</div></div>`}
