function migrateLegacyShows(rows){
  let changed=false;
  rows.forEach(show=>{
    const guest=guests.find(item=>item[0].toLowerCase()===String(show[3]).toLowerCase());if(!guest)return;
    const showDate=agendaDate(show[1]),sameDate=row=>{const date=agendaDate(row[1]);return date&&showDate&&date.getFullYear()===showDate.getFullYear()&&date.getMonth()===showDate.getMonth()&&date.getDate()===showDate.getDate()};
    const existing=agenda.find(row=>row[2].toLowerCase()===guest[0].toLowerCase()&&sameDate(row)&&!String(row[5]).toLowerCase().includes("reunião"));
    if(existing){existing[0]=show[2];existing[3]=guest[1];existing[4]=guest[9];existing[5]=String(existing[5]).includes("·")?`${show[5]} · ${String(existing[5]).split("·").slice(1).join("·").trim()}`:show[5];existing[7]=show[6];existing[10]="Sim";changed=true;return}
    agenda.push([show[2],show[1],guest[0],guest[1],guest[9],show[5],"",show[6],"Importado da antiga grade.",uid(),"Sim"]);
    changed=true;
  });
  return changed;
}
function gradeShows(){
  const days=["DOM","SEG","TER","QUA","QUI","SEX","SÁB"],months=["JAN","FEV","MAR","ABR","MAI","JUN","JUL","AGO","SET","OUT","NOV","DEZ"];
  return agenda.map(row=>({row,date:agendaDate(row[1]),guest:guests.find(item=>item[0].toLowerCase()===String(row[2]).toLowerCase())})).filter(item=>item.date&&item.guest&&item.row[7]!=="Cancelado"&&(item.row[10]==="Sim"||(item.row[10]===undefined&&!String(item.row[5]).toLowerCase().includes("reunião")))).sort((a,b)=>a.date-b.date||String(a.row[0]).localeCompare(String(b.row[0]))).map(({row,date,guest})=>[days[date.getDay()],`${String(date.getDate()).padStart(2,"0")} ${months[date.getMonth()]}`,row[0],guest[0],guest[1]||row[3],String(row[5]||"Programa").split("·")[0].trim().toUpperCase(),row[7],guest[9]||row[4],row[9],"agenda",row]);
}
